"""Half-open integer interval utilities: merge, free_gaps, max_overlap."""

from typing import Iterable, List, Sequence, Tuple

Interval = Tuple[int, int]


def _normalize(intervals: Iterable[Sequence[int]]) -> List[Interval]:
    """Return non-empty intervals as (start, end) tuples sorted by start."""
    out = [(int(s), int(e)) for s, e in intervals if s < e]
    out.sort()
    return out


def merge(intervals: Iterable[Sequence[int]]) -> List[Interval]:
    """Merge overlapping and touching intervals; drop empty ones."""
    result: List[Interval] = []
    for start, end in _normalize(intervals):
        if result and start <= result[-1][1]:
            if end > result[-1][1]:
                result[-1] = (result[-1][0], end)
        else:
            result.append((start, end))
    return result


def free_gaps(intervals: Iterable[Sequence[int]], window: Sequence[int]) -> List[Interval]:
    """Maximal sub-ranges of window not covered by any interval."""
    ws, we = window
    if ws >= we:
        return []
    gaps: List[Interval] = []
    cursor = ws
    for start, end in merge(intervals):
        if end <= cursor:
            continue
        if start > cursor:
            gaps.append((cursor, min(start, we)))
        cursor = max(cursor, end)
        if cursor >= we:
            break
    if cursor < we:
        gaps.append((cursor, we))
    return gaps


def max_overlap(intervals: Iterable[Sequence[int]]) -> int:
    """Largest number of intervals covering one common point (half-open)."""
    events = []
    for start, end in _normalize(intervals):
        events.append((start, 1))
        events.append((end, -1))
    events.sort()  # at equal coordinates, (x, -1) sorts before (x, 1): touching does not overlap

    best = 0
    depth = 0
    for _, delta in events:
        depth += delta
        if depth > best:
            best = depth
    return best

"""LRU cache with per-entry time-to-live (TTL).

See README.md for the specification.
"""

import time
from collections import OrderedDict


class TTLCache:
    """A fixed-capacity LRU cache where each entry may have its own TTL."""

    def __init__(self, capacity, clock=time.monotonic):
        if capacity < 1:
            raise ValueError("capacity must be at least 1")
        if not callable(clock):
            raise TypeError("clock must be a zero-argument callable")
        self._capacity = capacity
        self._clock = clock
        # Ordered least-recently-used first: key -> (value, expires_at or None).
        self._entries = OrderedDict()

    # ------------------------------------------------------------------ #
    # internal helpers
    # ------------------------------------------------------------------ #
    def _expired(self, expires_at):
        """An entry stored at t with lifetime ttl expires when clock() >= t + ttl."""
        return expires_at is not None and self._clock() >= expires_at

    def _purge_expired(self):
        now = self._clock()
        dead = [
            key
            for key, (_, expires_at) in self._entries.items()
            if expires_at is not None and now >= expires_at
        ]
        for key in dead:
            del self._entries[key]
        return len(dead)

    # ------------------------------------------------------------------ #
    # public API
    # ------------------------------------------------------------------ #
    def put(self, key, value, ttl=None):
        if ttl is not None and ttl <= 0:
            raise ValueError("ttl must be greater than 0")
        expires_at = None if ttl is None else self._clock() + ttl

        entry = self._entries.get(key)
        if entry is not None:
            # Existing key: replace value, restart lifetime, become most recent.
            # An already-expired entry is treated as absent (a new insertion).
            if self._expired(entry[1]):
                del self._entries[key]
            else:
                self._entries[key] = (value, expires_at)
                self._entries.move_to_end(key)
                return

        if len(self._entries) >= self._capacity:
            # A new key would exceed capacity: drop expired entries first,
            # then fall back to evicting the least recently used entries.
            self._purge_expired()
            while len(self._entries) >= self._capacity:
                self._entries.popitem(last=False)

        self._entries[key] = (value, expires_at)

    def get(self, key, default=None):
        entry = self._entries.get(key)
        if entry is None:
            return default
        if self._expired(entry[1]):
            del self._entries[key]
            return default
        self._entries.move_to_end(key)
        return entry[0]

    def __contains__(self, key):
        entry = self._entries.get(key)
        if entry is None:
            return False
        if self._expired(entry[1]):
            del self._entries[key]
            return False
        return True  # membership must not refresh recency

    def __len__(self):
        self._purge_expired()
        return len(self._entries)

    def keys(self):
        self._purge_expired()
        return list(self._entries.keys())

    def evict_expired(self):
        return self._purge_expired()

"""Arithmetic expression evaluator.

A hand-written tokenizer and recursive-descent parser (no eval/exec/compile/ast).

Grammar (lowest to highest precedence):
    expr    := term (('+' | '-') term)*
    term    := factor (('*' | '/' | '//' | '%') factor)*
    factor  := ('+' | '-') factor | power
    power   := primary ('**' factor)?          # right-associative
    primary := NUMBER | NAME '(' args ')' | '(' expr ')'
"""

_DIGITS = "0123456789"
_LETTERS = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ_"


class _Token:
    __slots__ = ("kind", "value")

    def __init__(self, kind, value=None):
        self.kind = kind
        self.value = value

    def __repr__(self):
        return "Token(%r, %r)" % (self.kind, self.value)


def _tokenize(text):
    tokens = []
    i = 0
    n = len(text)
    while i < n:
        ch = text[i]
        if ch.isspace():
            i += 1
            continue
        if ch in _DIGITS or ch == ".":
            start = i
            seen_dot = False
            while i < n and (text[i] in _DIGITS or (text[i] == "." and not seen_dot)):
                if text[i] == ".":
                    seen_dot = True
                i += 1
            lexeme = text[start:i]
            if lexeme == ".":
                raise ValueError("malformed number %r" % lexeme)
            tokens.append(_Token("NUMBER", float(lexeme) if seen_dot else int(lexeme)))
            continue
        if ch in _LETTERS:
            start = i
            while i < n and (text[i] in _LETTERS or text[i] in _DIGITS):
                i += 1
            tokens.append(_Token("NAME", text[start:i]))
            continue
        if text.startswith("**", i):
            tokens.append(_Token("OP", "**"))
            i += 2
            continue
        if ch in "+-*/%(),":
            tokens.append(_Token("COMMA" if ch == "," else "OP", ch))
            i += 1
            continue
        raise ValueError("unknown character %r at position %d" % (ch, i))
    tokens.append(_Token("EOF"))
    return tokens


class _Parser:
    def __init__(self, tokens):
        self._tokens = tokens
        self._pos = 0

    def _peek(self):
        return self._tokens[self._pos]

    def _next(self):
        token = self._tokens[self._pos]
        self._pos += 1
        return token

    def _expect(self, kind, value=None):
        token = self._next()
        if token.kind != kind or (value is not None and token.value != value):
            raise ValueError("expected %r, got %r" % (value if value else kind, token))
        return token

    def parse(self):
        value = self._expr()
        token = self._next()
        if token.kind != "EOF":
            raise ValueError("unexpected trailing token %r" % (token,))
        return value

    def _expr(self):
        value = self._term()
        while True:
            token = self._peek()
            if token.kind == "OP" and token.value in ("+", "-"):
                self._next()
                rhs = self._term()
                value = value + rhs if token.value == "+" else value - rhs
            else:
                return value

    def _term(self):
        value = self._factor()
        while True:
            token = self._peek()
            if token.kind == "OP" and token.value in ("*", "/", "//", "%"):
                self._next()
                rhs = self._factor()
                if token.value == "*":
                    value = value * rhs
                elif token.value == "/":
                    value = value / rhs
                elif token.value == "//":
                    value = value // rhs
                else:
                    value = value % rhs
            else:
                return value

    def _factor(self):
        token = self._peek()
        if token.kind == "OP" and token.value in ("+", "-"):
            self._next()
            value = self._factor()
            return value if token.value == "+" else -value
        return self._power()

    def _power(self):
        base = self._primary()
        token = self._peek()
        if token.kind == "OP" and token.value == "**":
            self._next()
            return base ** self._factor()
        return base

    def _primary(self):
        token = self._next()
        if token.kind == "NUMBER":
            return token.value
        if token.kind == "OP" and token.value == "(":
            value = self._expr()
            self._expect("OP", ")")
            return value
        if token.kind == "NAME":
            name = token.value
            self._expect("OP", "(")
            args = [self._expr()]
            while self._peek().kind == "COMMA":
                self._next()
                args.append(self._expr())
            self._expect("OP", ")")
            if name in ("min", "max"):
                if not args:
                    raise ValueError("%s() needs at least one argument" % name)
                return min(args) if name == "min" else max(args)
            if name == "abs":
                if len(args) != 1:
                    raise ValueError("abs() takes exactly one argument")
                return abs(args[0])
            raise ValueError("unknown name %r" % name)
        raise ValueError("unexpected token %r" % (token,))


def evaluate(text):
    """Parse and evaluate an arithmetic expression string."""
    if not isinstance(text, str):
        raise ValueError("input must be a string")
    return _Parser(_tokenize(text)).parse()
